import { mkdir, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';

const outputPath = resolve(process.cwd(), 'docs/generated/skopos/workflow-note.md');
const contents = [
  '# Workflow Note',
  '',
  'Generated by the fixture Skopos workflow.',
  '',
  '- source: `tools/skopos/workflows/docs-generate-note.yaml`',
  '- purpose: prove workflow discovery and execution',
  '',
].join('\n');

await mkdir(dirname(outputPath), { recursive: true });
await writeFile(outputPath, contents, 'utf8');
